1	import { access, cp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
2	import { basename, dirname, join, relative, resolve } from 'pathe';
3	import { canonicalize, sha256 } from '../../../core/src/receipts/canonicalize.ts';
4	import {
5		parseWitnessReactPapercupsReceipt,
6		REACT_PAPERCUPS_CANONICAL_DIGEST,
7		REACT_PAPERCUPS_RECEIPT_PATH,
8		REACT_PAPERCUPS_RECEIPT_SHA256,
9		REACT_PAPERCUPS_SOURCE,
10		REACT_PAPERCUPS_FIXTURE,
11		renderWitnessReactPapercupsReceipt,
12		WITNESS_REACT_PAPERCUPS_SCHEMA,
13		witnessReactPapercupsBehaviorDigest,
14		witnessReactPapercupsDigest,
15		witnessReactPapercupsRawDigest,
16		type WitnessReactPapercupsMutation,
17		type WitnessReactPapercupsReceipt,
18		type WitnessReactPapercupsRun,
19	} from '../../../core/src/receipts/witness-react-papercups.ts';
20	import { executeReactPapercupsWitnessRun } from './real-app-run.ts';
21	import { verifyLinkedWitnessProvenance } from './provenance.ts';
22	
23	const root = resolve(import.meta.dirname, '../../../..');
24	const fixtureEvidence = join(root, 'evidence/runs/react-papercups-v1-0-0');
25	const witnessEvidence = join(root, 'evidence/runs/witness-react-papercups');
26	const stageRoot = join(root, '.versionless/stage/witness-react-papercups');
27	const sourceOutputs = {
28		baseline: join(root, '.versionless/work/react-papercups-v1-0-0/baseline/build'),
29		migrated: join(root, '.versionless/work/react-papercups-v1-0-0/target/build-vite'),
30	} as const;
31	
32	/**
33	 * Visible sign-in heading shipped inside the migrated module. It is the first
34	 * text the journey asserts, so replacing its bytes must make the browser
35	 * journey genuinely red rather than merely changing an unread constant.
36	 */
37	const MUTATION_SEAM = 'Welcome back' as const;
38	
39	async function exists(path: string): Promise<boolean> {
40		return access(path).then(
41			() => true,
42			() => false,
43		);
44	}
45	
46	async function files(directory: string): Promise<string[]> {
47		const output: string[] = [];
48		for (const entry of await readdir(directory, { withFileTypes: true })) {
49			const path = join(directory, entry.name);
50			if (entry.isDirectory()) output.push(...(await files(path)));
51			else if (entry.isFile()) output.push(path);
52		}
53		return output.sort();
54	}
55	
56	async function stageInputs(): Promise<Record<'baseline' | 'migrated', string>> {
57		const lanes = join(stageRoot, 'lanes');
58		await rm(lanes, { recursive: true, force: true });
59		const staged = { baseline: join(lanes, 'baseline'), migrated: join(lanes, 'migrated') };
60		for (const lane of ['baseline', 'migrated'] as const) {
61			if (!(await exists(sourceOutputs[lane])))
62				throw new Error(`Papercups ${lane} production output is absent`);
63			await mkdir(dirname(staged[lane]), { recursive: true });
64			await cp(sourceOutputs[lane], staged[lane], { recursive: true, force: false });
65		}
66		return staged;
67	}
68	
69	async function executeRuns(
70		lanes: Record<'baseline' | 'migrated', string>,
71	): Promise<WitnessReactPapercupsRun[]> {
72		const runs: WitnessReactPapercupsRun[] = [];
73		for (const lane of ['baseline', 'migrated'] as const)
74			for (const pass of [1, 2] as const) {
75				const raw = await executeReactPapercupsWitnessRun({
76					lane,
77					pass,
78					laneRoot: lanes[lane],
79					receiptRoot: join(stageRoot, 'receipts'),
80				});
81				const run = raw as WitnessReactPapercupsRun;
82				if (run.semanticDigest !== witnessReactPapercupsRawDigest(run))
83					throw new Error(`Papercups ${lane} pass ${pass} raw digest differs`);
84				runs.push({ ...run, behaviorDigest: witnessReactPapercupsBehaviorDigest(run) });
85			}
86		if (new Set(runs.map((run) => run.behaviorDigest)).size !== 1)
87			throw new Error('Papercups baseline/migrated behavior parity differs');
88		return runs;
89	}
90	
91	/**
92	 * Byte mutation on the migrated build: locate the visible sign-in heading in
93	 * the served module, overwrite it in place with an equal-length filler, require
94	 * the journey to go red on that exact assertion, restore the original bytes,
95	 * and require the restored journey to reproduce the parity behavior digest.
96	 */
97	async function semanticMutation(
98		laneRoot: string,
99		behaviorDigest: string,
100	): Promise<WitnessReactPapercupsMutation> {
101		const expected = Buffer.from(MUTATION_SEAM);
102		const candidates: Array<{ path: string; offset: number }> = [];
103		for (const path of await files(laneRoot)) {
104			const bytes = await readFile(path);
105			const offset = bytes.indexOf(expected);
106			if (offset < 0) continue;
107			if (bytes.lastIndexOf(expected) !== offset)
108				throw new Error('Papercups semantic seam is not unique within its file');
109			candidates.push({ path, offset });
110		}
111		const modules = candidates.filter((candidate) => candidate.path.endsWith('.js'));
112		const target = modules[0];
113		if (
114			modules.length !== 1 ||
115			target === undefined ||
116			canonicalize(candidates.map((candidate) => candidate.path).sort()) !==
117				canonicalize([target.path, `${target.path}.map`].sort())
118		)
119			throw new Error('Papercups semantic seam is not a single served module and its sourcemap');
120		const before = await readFile(target.path);
121		const mutated = Buffer.from(before);
122		Buffer.alloc(expected.length, 'X').copy(mutated, target.offset);
123		const beforeSha256 = sha256(before);
124		const mutatedSha256 = sha256(mutated);
125		let intendedFailure = false;
126		try {
127			await writeFile(target.path, mutated);
128			try {
129				await executeReactPapercupsWitnessRun({
130					lane: 'migrated',
131					pass: 1,
132					laneRoot,
133					receiptRoot: join(stageRoot, 'mutation-receipt'),
134				});
135			} catch (error) {
136				const message = error instanceof Error ? error.message : String(error);
137				intendedFailure = message.includes(MUTATION_SEAM);
138			}
139		} finally {
140			await writeFile(target.path, before);
141		}
142		const afterRestoreSha256 = sha256(await readFile(target.path));
143		if (!intendedFailure || afterRestoreSha256 !== beforeSha256)
144			throw new Error('Papercups semantic mutation was not exact red and byte-restored');
145		const restored = (await executeReactPapercupsWitnessRun({
146			lane: 'migrated',
147			pass: 1,
148			laneRoot,
149			receiptRoot: join(stageRoot, 'restoration-receipt'),
150		})) as WitnessReactPapercupsRun;
151		const restoredBehaviorDigest = witnessReactPapercupsBehaviorDigest(restored);
152		if (restoredBehaviorDigest !== behaviorDigest)
153			throw new Error('Papercups restored browser behavior differs');
154		return {
155			failure: 'witness-semantic-assertion',
156			intendedFailure: true,
157			lane: 'migrated',
158			seam: MUTATION_SEAM,
159			path: relative(laneRoot, target.path),
160			offset: target.offset,
161			beforeSha256,
162			mutatedSha256,
163			afterRestoreSha256,
164			restoredByteIdentically: true,
165			restoredRun: 'pass',
166			restoredBehaviorDigest,
167		};
168	}
169	
170	export async function runWitnessReactPapercups(): Promise<WitnessReactPapercupsReceipt> {
171		if (
172			process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
173			process.env.NPM_CONFIG_OFFLINE !== 'true'
174		)
175			throw new Error('Papercups Witness requires dual offline controls');
176		if (await exists(witnessEvidence)) throw new Error('Papercups Witness output collision');
177		const provenance = await verifyLinkedWitnessProvenance(root);
178		const canonicalBytes = await readFile(join(root, REACT_PAPERCUPS_RECEIPT_PATH));
179		const canonical = JSON.parse(canonicalBytes.toString('utf8')) as {
180			fixture?: unknown;
181			integrity: { canonicalDigest: string };
182		};
183		if (
184			canonical.fixture !== REACT_PAPERCUPS_FIXTURE ||
185			canonical.integrity.canonicalDigest !== REACT_PAPERCUPS_CANONICAL_DIGEST ||
186			sha256(canonicalBytes) !== REACT_PAPERCUPS_RECEIPT_SHA256
187		)
188			throw new Error('Papercups canonical build receipt identity differs');
189		const lanes = await stageInputs();
190		const runs = await executeRuns(lanes);
191		const mutation = await semanticMutation(lanes.migrated, runs[0]!.behaviorDigest);
192		const zeroServiceWorker = {
193			registration: 'application-unregister' as const,
194			checkpoints: runs[0]!.zeroServiceWorkerRuntime.checkpoints,
195			emittedOutputFiles: runs
196				.flatMap((run) => run.zeroServiceWorkerRuntime.emittedOutputFiles)
197				.filter(
198					(file, index, all) =>
199						all.findIndex((item) => canonicalize(item) === canonicalize(file)) === index,
200				)
201				.sort((left, right) => left.path.localeCompare(right.path)),
202			requests: [] as [],
203			workerEvents: [] as [],
204		};
205		const artifacts = join(fixtureEvidence, 'artifacts');
206		await mkdir(artifacts, { recursive: true });
207		await writeFile(join(artifacts, 'witness-journeys.json'), `${canonicalize(runs)}\n`, {
208			flag: 'wx',
209		});
210		await writeFile(join(artifacts, 'witness-mutation.json'), `${canonicalize(mutation)}\n`, {
211			flag: 'wx',
212		});
213		const receipt: WitnessReactPapercupsReceipt = {
214			schemaVersion: WITNESS_REACT_PAPERCUPS_SCHEMA,
215			result: 'pass',
216			fixture: REACT_PAPERCUPS_FIXTURE,
217			source: REACT_PAPERCUPS_SOURCE,
218			provenance,
219			canonicalReceipt: {
220				path: REACT_PAPERCUPS_RECEIPT_PATH,
221				canonicalDigest: canonical.integrity.canonicalDigest,
222				sha256: sha256(canonicalBytes),
223			},
224			runs,
225			mutation,
226			zeroServiceWorker,
227			scrollSurface: {
228				state: 'omitted-not-meaningful',
229				viewport: { width: 1280, height: 720 },
230				observation: 'scrollHeight-equals-clientHeight-on-every-visited-route',
231				claimed: false,
232			},
233			readiness: {
234				reactLineage: { ready: 1, total: 4, counted: false },
235				overall: { ready: 3, total: 12 },
236			},
237			locality: { mode: 'offline', successfulNonLoopback: 0, osWideIsolation: false },
238			nonclaims: [
239				'This is one React lineage under direct Witness and does not establish generic React or create-react-app support.',
240				'The React lineage readiness score is unchanged at 1/4; this vertical is not counted before Judge audit.',
241				'Scroll is not tested: every route the journey visits reports scrollHeight equal to clientHeight at 1280x720, so there is no meaningful scroll surface to exercise.',
242				'Drag is not tested because the operator console has no genuine drag surface on the visited routes.',
243				'The retained create-react-app baseline still emits an unregistered service-worker.js; the evidence records those bytes and proves the runtime never registers, controls, caches, or requests them.',
244				'The Papercups API and Phoenix socket are answered by a frozen synthetic loopback projection authored for this fixture; no captured production payload and no real customer data are involved.',
245				'Locality is process-scoped and does not establish operating-system-wide isolation.',
246				'Receipts prove reproducibility and hash integrity, not certification, authenticity, signer identity, compliance, or an earned SLSA level.',
247			],
248			integrity: { algorithm: 'sha256', canonicalDigest: '' },
249		};
250		receipt.integrity.canonicalDigest = witnessReactPapercupsDigest(receipt);
251		parseWitnessReactPapercupsReceipt(receipt);
252		await mkdir(witnessEvidence, { recursive: true });
253		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonicalize(receipt)}\n`, {
254			flag: 'wx',
255		});
256		await writeFile(
257			join(witnessEvidence, 'receipt.md'),
258			renderWitnessReactPapercupsReceipt(receipt),
259			{ flag: 'wx' },
260		);
261		return receipt;
262	}
263	
264	export async function verifyWitnessReactPapercups(
265		output = witnessEvidence,
266	): Promise<WitnessReactPapercupsReceipt> {
267		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
268		const receipt = parseWitnessReactPapercupsReceipt(
269			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
270		);
271		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
272			throw new Error('Papercups linked Witness provenance differs');
273		const canonicalBytes = await readFile(join(root, receipt.canonicalReceipt.path));
274		if (sha256(canonicalBytes) !== receipt.canonicalReceipt.sha256)
275			throw new Error('Papercups canonical receipt bytes drifted');
276		if (
277			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
278			renderWitnessReactPapercupsReceipt(receipt)
279		)
280			throw new Error('Papercups human Witness receipt differs');
281		const serialized = canonicalize(receipt);
282		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
283			throw new Error('Papercups receipt leaks host identity');
284		return receipt;
285	}
286	
287	export async function main(args = process.argv.slice(2)): Promise<void> {
288		const publishIndex = args.indexOf('--publish');
289		const verifyIndex = args.indexOf('--verify');
290		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
291			const output = resolve(root, args[publishIndex + 1]!);
292			if (output !== witnessEvidence) throw new Error('Papercups publish path differs');
293			const receipt = await runWitnessReactPapercups();
294			process.stdout.write(
295				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
296			);
297			return;
298		}
299		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
300			const receipt = await verifyWitnessReactPapercups(resolve(root, args[verifyIndex + 1]!));
301			process.stdout.write(
302				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
303			);
304			return;
305		}
306		throw new Error('Papercups Witness runner requires --run-twice --publish <dir> or --verify <dir>');
307	}
308	
309	if (basename(process.argv[1] ?? '') === 'react-papercups-run.ts')
310		main().catch((error: unknown) => {
311			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
312			process.exitCode = 1;
313		});
