305	export type MemosProjectionDecision =
306		| 'served'
307		| 'refused-unknown'
308		| 'refused-unprojected'
309		| 'declined-non-api';
310	
311	export type MemosProjectionLedgerRecord = {
312		sequence: number;
313		method: string;
314		pathname: string;
315		search: string;
316		endpoint: string | null;
317		decision: MemosProjectionDecision;
318		status: number | null;
319		/** Whether a session stood open once this decision had been taken. */
320		authenticated: boolean;
321		requestSha256: string;
322		responseSha256: string | null;
323	};
324	
325	export type MemosProjection = {
326		api(request: MemosApiRequest): Promise<MemosApiResponse | null>;
327		ledger(): MemosProjectionLedgerRecord[];
328		sessionUserId(): number | null;
329		memos(): MemosMemo[];
330		shortcuts(): MemosShortcut[];
331		users(): MemosUser[];
332	};
333	
334	/**
335	 * The endpoints this projection answers, keyed by the ledger id it records.
336	 * `POST /api/resource` is enumerated in the pinned client and deliberately NOT
337	 * projected: nothing in the journey surface uploads a file, and answering an
338	 * upload would mean inventing a resource pipeline whose bytes no witness ever
339	 * sees.
340	 */
341	export const MEMOS_PROJECTED_ENDPOINTS = Object.freeze([
342		'status',
343		'auth.login',
344		'auth.signup',
345		'auth.logout',
346		'user.create',
347		'user.list',
348		'user.me.get',
349		'user.me.patch',
350		'memo.list',
351		'memo.create',
352		'memo.patch',
353		'memo.organizer',
354		'memo.delete',
355		'tag.list',
356		'shortcut.list',
357		'shortcut.create',
358		'shortcut.patch',
359		'shortcut.delete',
360	] as const);
361	
362	export const MEMOS_UNPROJECTED_ENDPOINTS = Object.freeze([
363		{
364			endpoint: 'resource.upload',
365			method: 'POST',
366			path: '/api/resource',
367			reason:
368				'no journey uploads a file; projecting an upload would mean inventing a resource ' +
369				'pipeline and a `/h/r/:id/:filename` byte stream that no witness observes',
370		},
371	] as const);
372	
373	function json(value: unknown, status = 200): MemosApiResponse {
374		return {
375			status,
376			contentType: 'application/json',
377			body: Buffer.from(JSON.stringify(value), 'utf8'),
378		};
379	}
380	
381	const envelope = (data: unknown, status = 200): MemosApiResponse => json({ data }, status);
382	
383	const failure = (status: number, error: string, message: string): MemosApiResponse =>
384		json({ error, message }, status);
385	
386	const unknownPath = (method: string, pathname: string): MemosApiResponse =>
387		failure(
388			404,
389			'unknown-endpoint',
390			`Memos synthetic projection refuses an endpoint the pinned client never calls: ${method} ${pathname}`,
391		);
392	
393	const unprojectedPath = (endpoint: string, reason: string): MemosApiResponse =>
394		failure(
395			501,
396			'unprojected-endpoint',
397			`Memos synthetic projection withholds the enumerated endpoint ${endpoint}: ${reason}`,
398		);
399	
400	function parsedBody(body: Buffer): Record<string, unknown> {
401		if (body.length === 0) return {};
402		const parsed: unknown = JSON.parse(body.toString('utf8'));
403		if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed))
404			throw new Error('Memos synthetic projection requires a JSON object body');
405		return parsed as Record<string, unknown>;
406	}
407	
408	const stringField = (source: Record<string, unknown>, key: string): string | null => {
409		const value = source[key];
410		return typeof value === 'string' ? value : null;
411	};
412	
413	const queryValue = (query: Record<string, string | string[]>, key: string): string | null => {
414		const value = query[key];
415		if (typeof value === 'string') return value;
416		return Array.isArray(value) && typeof value[0] === 'string' ? value[0] : null;
417	};
418	
419	const numericSuffix = (pathname: string, prefix: string, suffix = ''): number | null => {
420		if (!pathname.startsWith(prefix) || !pathname.endsWith(suffix)) return null;
421		const raw = pathname.slice(prefix.length, pathname.length - suffix.length);
422		if (raw.length === 0 || raw.split('').some((digit) => digit < '0' || digit > '9')) return null;
423		return Number.parseInt(raw, 10);
424	};
425	
426	type Handled = { endpoint: string; response: MemosApiResponse };
427	
428	/**
429	 * One projection instance. `createMemosProjection()` is called once per run by
430	 * the loopback seam, so every run starts from the frozen seed rather than
431	 * inheriting another run's mutations.
432	 */
433	export function createMemosProjection(): MemosProjection {
434		const users: MemosUser[] = MEMOS_SEED.users.map((user) => structuredClone(user));
435		const passwords = new Map<number, string>(
436			MEMOS_SEED.credentials.map((entry) => [entry.userId, entry.password]),
437		);
438		const memos: MemosMemo[] = MEMOS_SEED.memos.map((record) => structuredClone(record));
439		const shortcuts: MemosShortcut[] = MEMOS_SEED.shortcuts.map((record) =>
440			structuredClone(record),
441		);
442		const records: MemosProjectionLedgerRecord[] = [];
443		let session: number | null = null;
444		let mutations = 0;
445		let sequence = 0;
446	
447		const tick = (): number => {
448			const stamp = MUTATION_CLOCK_ORIGIN_SECONDS + mutations * MUTATION_CLOCK_STEP_SECONDS;
449			mutations += 1;
450			return stamp;
451		};
452		const nextId = (rows: readonly { id: number }[]): number =>
453			rows.reduce((highest, row) => (row.id > highest ? row.id : highest), 0) + 1;
454		const sessionUser = (): MemosUser | null => users.find((user) => user.id === session) ?? null;
455		const owner = (): MemosUser | null => users.find((user) => user.role === 'OWNER') ?? null;
456		const byCreated = (left: { createdTs: number }, right: { createdTs: number }): number =>
457			right.createdTs - left.createdTs;
458	
459		const unauthorized = (): MemosApiResponse =>
460			failure(401, 'unauthorized', 'Memos synthetic projection has no session for this request');
461	
462		const createUser = (
463			body: Record<string, unknown>,
464			role: MemosUserRole,
465		): MemosUser | MemosApiResponse => {
466			const email = stringField(body, 'email');
467			const password = stringField(body, 'password');
468			if (email === null || email.length === 0 || password === null || password.length === 0)
469				return failure(
470					400,
471					'invalid-request',
472					'Memos synthetic projection requires email and password',
473				);
474			if (users.some((user) => user.email === email))
475				return failure(
476					400,
477					'duplicate-user',
478					`Memos synthetic projection already holds ${email}`,
479				);
480			const stamp = tick();
481			const created: MemosUser = {
482				id: nextId(users),
483				createdTs: stamp,
484				updatedTs: stamp,
485				rowStatus: 'NORMAL',
486				role,
487				email,
488				name: stringField(body, 'name') ?? email,
489				openId: `synthetic-open-id-${nextId(users)}`,
490			};
491			users.push(created);
492			passwords.set(created.id, password);
493			return created;
494		};
495	
496		const patchMe = (user: MemosUser, body: Record<string, unknown>): MemosApiResponse => {
497			const name = stringField(body, 'name');
498			const password = stringField(body, 'password');
499			if (name !== null && name.length > 0) user.name = name;
500			if (password !== null && password.length > 0) passwords.set(user.id, password);
501			if (body['resetOpenId'] === true) user.openId = `synthetic-open-id-reset-${tick()}`;
502			user.updatedTs = tick();
503			return envelope(structuredClone(user));
504		};
505	
506		const memoList = (user: MemosUser, search: string): MemosApiResponse => {
507			const rowStatus = queryValue(parseQuery(search), 'rowStatus');
508			const visible = memos
509				.filter((record) => record.creatorId === user.id)
510				.filter((record) => rowStatus === null || record.rowStatus === rowStatus)
511				.sort(byCreated);
512			return envelope(structuredClone(visible));
513		};
514	
515		const createMemo = (user: MemosUser, body: Record<string, unknown>): MemosApiResponse => {
516			const content = stringField(body, 'content');
517			if (content === null || content.trim().length === 0)
518				return failure(
519					400,
520					'invalid-request',
521					'Memos synthetic projection requires memo content',
522				);
523			const declared = body['createdTs'];
524			const stamp = typeof declared === 'number' ? declared : tick();
525			const created: MemosMemo = {
526				id: nextId(memos),
527				creatorId: user.id,
528				createdTs: stamp,
529				updatedTs: stamp,
530				rowStatus: 'NORMAL',
531				content,
532				pinned: false,
533			};
534			memos.push(created);
535			return envelope(structuredClone(created));
536		};
537	
538		const ownedMemo = (user: MemosUser, id: number): MemosMemo | null =>
539			memos.find((record) => record.id === id && record.creatorId === user.id) ?? null;
540	
541		const patchMemo = (
542			user: MemosUser,
543			id: number,
544			body: Record<string, unknown>,
545		): MemosApiResponse => {
546			const record = ownedMemo(user, id);
547			if (record === null)
548				return failure(404, 'not-found', `Memos synthetic projection holds no memo ${id}`);
549			const content = stringField(body, 'content');
550			const rowStatus = stringField(body, 'rowStatus');
551			if (content !== null) record.content = content;
552			if (rowStatus === 'NORMAL' || rowStatus === 'ARCHIVED') record.rowStatus = rowStatus;
553			record.updatedTs = tick();
554			return envelope(structuredClone(record));
555		};
556	
557		const organizeMemo = (
558			user: MemosUser,
559			id: number,
560			body: Record<string, unknown>,
561		): MemosApiResponse => {
562			const record = ownedMemo(user, id);
563			if (record === null)
564				return failure(404, 'not-found', `Memos synthetic projection holds no memo ${id}`);
565			if (typeof body['pinned'] !== 'boolean')
566				return failure(
567					400,
568					'invalid-request',
569					'Memos synthetic projection requires a pinned flag',
570				);
571			record.pinned = body['pinned'];
572			record.updatedTs = tick();
573			return envelope(structuredClone(record));
574		};
575	
576		const deleteMemo = (user: MemosUser, id: number): MemosApiResponse => {
577			const index = memos.findIndex((record) => record.id === id && record.creatorId === user.id);
578			if (index === -1)
579				return failure(404, 'not-found', `Memos synthetic projection holds no memo ${id}`);
580			memos.splice(index, 1);
581			return envelope(true);
582		};
583	
584		/** Tags of the session user's live memos, deduplicated and lexicographically ordered. */
585		const tagList = (user: MemosUser): MemosApiResponse => {
586			const tags = new Set<string>();
587			for (const record of memos)
588				if (record.creatorId === user.id && record.rowStatus === 'NORMAL')
589					for (const tag of memosTagsInContent(record.content)) tags.add(tag);
590			return envelope([...tags].sort());
591		};
592	
593		const ownedShortcut = (user: MemosUser, id: number): MemosShortcut | null =>
594			shortcuts.find((record) => record.id === id && record.creatorId === user.id) ?? null;
595	
596		const createShortcut = (user: MemosUser, body: Record<string, unknown>): MemosApiResponse => {
597			const title = stringField(body, 'title');
598			const payload = stringField(body, 'payload');
599			if (title === null || title.length === 0 || payload === null || payload.length === 0)
600				return failure(
601					400,
602					'invalid-request',
603					'Memos synthetic projection requires a shortcut title and payload',
604				);
605			const stamp = tick();
606			const created: MemosShortcut = {
607				id: nextId(shortcuts),
608				creatorId: user.id,
609				rowStatus: 'NORMAL',
610				createdTs: stamp,
611				updatedTs: stamp,
612				title,
613				payload,
614			};
615			shortcuts.push(created);
616			return envelope(structuredClone(created));
617		};
618	
619		const patchShortcut = (
620			user: MemosUser,
621			id: number,
622			body: Record<string, unknown>,
623		): MemosApiResponse => {
624			const record = ownedShortcut(user, id);
625			if (record === null)
626				return failure(404, 'not-found', `Memos synthetic projection holds no shortcut ${id}`);
627			const title = stringField(body, 'title');
628			const payload = stringField(body, 'payload');
629			const rowStatus = stringField(body, 'rowStatus');
630			if (title !== null && title.length > 0) record.title = title;
631			if (payload !== null && payload.length > 0) record.payload = payload;
632			if (rowStatus === 'NORMAL' || rowStatus === 'ARCHIVED') record.rowStatus = rowStatus;
633			record.updatedTs = tick();
634			return envelope(structuredClone(record));
635		};
636	
637		const deleteShortcut = (user: MemosUser, id: number): MemosApiResponse => {
638			const index = shortcuts.findIndex(
639				(record) => record.id === id && record.creatorId === user.id,
640			);
641			if (index === -1)
642				return failure(404, 'not-found', `Memos synthetic projection holds no shortcut ${id}`);
643			shortcuts.splice(index, 1);
644			return envelope(true);
645		};
646	
647		const login = (body: Record<string, unknown>): MemosApiResponse => {
648			const email = stringField(body, 'email');
649			const password = stringField(body, 'password');
650			const user = users.find((candidate) => candidate.email === email) ?? null;
651			if (user === null || password === null || passwords.get(user.id) !== password)
652				return failure(
653					401,
654					'unauthorized',
655					'Memos synthetic projection rejects these sign-in values',
656				);
657			session = user.id;
658			return envelope(structuredClone(user));
659		};
660	
661		/**
662		 * Signup. The pinned client only offers this button while `/api/status`
663		 * reports no owner, and it always asks for `OWNER`. The projection grants
664		 * `OWNER` only when no owner exists and otherwise records the account as a
665		 * plain `USER`, so the role in the store is a decision this projection made
666		 * rather than a role the client asserted.
667		 */
668		const signup = (body: Record<string, unknown>): MemosApiResponse => {
669			const created = createUser(body, owner() === null ? 'OWNER' : 'USER');
670			if (!('id' in created)) return created;
671			session = created.id;
672			return envelope(structuredClone(created));
673		};
674	
675		const authenticated = (handler: (user: MemosUser) => MemosApiResponse): MemosApiResponse => {
676			const user = sessionUser();
677			return user === null ? unauthorized() : handler(user);
678		};
679	
680		const handleUser = (request: MemosApiRequest, body: Buffer): Handled | null => {
681			if (request.pathname === '/api/user' && request.method === 'GET')
682				return {
683					endpoint: 'user.list',
684					response: authenticated(() => envelope(structuredClone(users))),
685				};
686			if (request.pathname === '/api/user' && request.method === 'POST')
687				return {
688					endpoint: 'user.create',
689					response: authenticated((user) => {
690						if (user.role !== 'OWNER')
691							return failure(
692								403,
693								'forbidden',
694								'Memos synthetic projection lets only the owner create members',
695							);
696						const created = createUser(parsedBody(body), 'USER');
697						return 'id' in created ? envelope(structuredClone(created)) : created;
698					}),
699				};
700			if (request.pathname === '/api/user/me' && request.method === 'GET')
701				return {
702					endpoint: 'user.me.get',
703					response: authenticated((user) => envelope(structuredClone(user))),
704				};
705			if (request.pathname === '/api/user/me' && request.method === 'PATCH')
706				return {
707					endpoint: 'user.me.patch',
708					response: authenticated((user) => patchMe(user, parsedBody(body))),
709				};
710			return null;
711		};
712	
713		const handleMemo = (request: MemosApiRequest, body: Buffer): Handled | null => {
714			if (request.pathname === '/api/memo' && request.method === 'GET')
715				return {
716					endpoint: 'memo.list',
717					response: authenticated((user) => memoList(user, request.search)),
718				};
719			if (request.pathname === '/api/memo' && request.method === 'POST')
720				return {
721					endpoint: 'memo.create',
722					response: authenticated((user) => createMemo(user, parsedBody(body))),
723				};
724			const organizerId = numericSuffix(request.pathname, '/api/memo/', '/organizer');
725			if (organizerId !== null && request.method === 'POST')
726				return {
727					endpoint: 'memo.organizer',
728					response: authenticated((user) =>
729						organizeMemo(user, organizerId, parsedBody(body)),
730					),
731				};
732			const memoId = numericSuffix(request.pathname, '/api/memo/');
733			if (memoId !== null && request.method === 'PATCH')
734				return {
735					endpoint: 'memo.patch',
736					response: authenticated((user) => patchMemo(user, memoId, parsedBody(body))),
737				};
738			if (memoId !== null && request.method === 'DELETE')
739				return {
740					endpoint: 'memo.delete',
741					response: authenticated((user) => deleteMemo(user, memoId)),
742				};
743			return null;
744		};
745	
746		const handleShortcut = (request: MemosApiRequest, body: Buffer): Handled | null => {
747			if (request.pathname === '/api/shortcut' && request.method === 'GET')
748				return {
749					endpoint: 'shortcut.list',
750					response: authenticated((user) =>
751						envelope(
752							structuredClone(
753								shortcuts
754									.filter((record) => record.creatorId === user.id)
755									.sort(byCreated),
756							),
757						),
758					),
759				};
760			if (request.pathname === '/api/shortcut' && request.method === 'POST')
761				return {
762					endpoint: 'shortcut.create',
763					response: authenticated((user) => createShortcut(user, parsedBody(body))),
764				};
765			const shortcutId = numericSuffix(request.pathname, '/api/shortcut/');
766			if (shortcutId !== null && request.method === 'PATCH')
767				return {
768					endpoint: 'shortcut.patch',
769					response: authenticated((user) =>
770						patchShortcut(user, shortcutId, parsedBody(body)),
771					),
772				};
773			if (shortcutId !== null && request.method === 'DELETE')
774				return {
775					endpoint: 'shortcut.delete',
776					response: authenticated((user) => deleteShortcut(user, shortcutId)),
777				};
778			return null;
779		};
780	
781		const handle = (request: MemosApiRequest): Handled => {
782			const body = request.body;
783			if (request.pathname === '/api/status' && request.method === 'GET') {
784				const siteOwner = owner();
785				return {
786					endpoint: 'status',
787					response: envelope({
788						...(siteOwner === null ? {} : { owner: structuredClone(siteOwner) }),
789						profile: { ...MEMOS_SEED.profile },
790					}),
791				};
792			}
793			if (request.pathname === '/api/auth/login' && request.method === 'POST')
794				return { endpoint: 'auth.login', response: login(parsedBody(body)) };
795			if (request.pathname === '/api/auth/signup' && request.method === 'POST')
796				return { endpoint: 'auth.signup', response: signup(parsedBody(body)) };
797			if (request.pathname === '/api/auth/logout' && request.method === 'POST') {
798				session = null;
799				return { endpoint: 'auth.logout', response: envelope(true) };
800			}
801			if (request.pathname === '/api/tag' && request.method === 'GET')
802				return { endpoint: 'tag.list', response: authenticated((user) => tagList(user)) };
803			const withheld = MEMOS_UNPROJECTED_ENDPOINTS.find(
804				(entry) => entry.path === request.pathname && entry.method === request.method,
805			);
806			if (withheld !== undefined)
807				return {
808					endpoint: withheld.endpoint,
809					response: unprojectedPath(withheld.endpoint, withheld.reason),
810				};
811			const handled =
812				handleUser(request, body) ?? handleMemo(request, body) ?? handleShortcut(request, body);
813			return (
814				handled ?? {
815					endpoint: '',
816					response: unknownPath(request.method, request.pathname),
817				}
818			);
819		};
820	
821		const record = (
822			request: MemosApiRequest,
823			endpoint: string | null,
824			decision: MemosProjectionDecision,
825			response: MemosApiResponse | null,
826		): void => {
827			sequence += 1;
828			records.push({
829				sequence,
830				method: request.method,
831				pathname: request.pathname,
832				search: request.search,
833				endpoint,
834				decision,
835				status: response?.status ?? null,
836				authenticated: session !== null,
837				requestSha256: sha256(request.body),
838				responseSha256: response === null ? null : sha256(response.body),
839			});
840		};
841	
842		const api = async (request: MemosApiRequest): Promise<MemosApiResponse | null> => {
843			if (!request.pathname.startsWith('/api/')) {
844				record(request, null, 'declined-non-api', null);
845				return null;
846			}
847			const handled = handle(request);
848			const endpoint = handled.endpoint.length === 0 ? null : handled.endpoint;
849			const decision: MemosProjectionDecision =
850				endpoint === null
851					? 'refused-unknown'
852					: handled.response.status === 501
853						? 'refused-unprojected'
854						: 'served';
855			record(request, endpoint, decision, handled.response);
856			return handled.response;
857		};
858	
859		return {
860			api,
861			ledger: () => records.map((entry) => ({ ...entry })),
862			sessionUserId: () => session,
863			memos: () => structuredClone(memos),
864			shortcuts: () => structuredClone(shortcuts),
865			users: () => structuredClone(users),
866		};
867	}
868	
869	export type MemosTranscriptStep = {
870		method: string;
871		pathname: string;
872		search?: string;
873		body?: unknown;
874	};
875	
876	/**
877	 * The frozen behaviour transcript.
878	 *
879	 * It walks the whole journey surface the enumeration records — the signed-out
880	 * gate, the sign-in that opens it, the memo list, a memo written and edited,
881	 * archive and restore, the derived tag list, a shortcut created, the settings
882	 * patch, sign-out and the gate closing again — plus both refusals. Replaying it
883	 * through a fresh projection is what `MEMOS_PROJECTION_BEHAVIOR_DIGEST` covers.
884	 */
885	export const MEMOS_PROJECTION_BEHAVIOR_TRANSCRIPT: readonly MemosTranscriptStep[] = Object.freeze([
886		{ method: 'GET', pathname: '/index.html' },
887		{ method: 'GET', pathname: '/api/status' },
888		{ method: 'GET', pathname: '/api/user/me' },
889		{
890			method: 'POST',
891			pathname: '/api/auth/login',
892			body: { email: OWNER.email, password: 'wrong-synthetic-passphrase' },
893		},
