1	import React, { useCallback, useEffect, useMemo, useRef } from "react";
2	import { editorStateService, locationService, memoService, resourceService } from "../services";
3	import { useAppSelector } from "../store";
4	import { UNKNOWN_ID } from "../helpers/consts";
5	import * as storage from "../helpers/storage";
6	import useToggle from "../hooks/useToggle";
7	import toastHelper from "./Toast";
8	import Editor, { EditorRefActions } from "./Editor/Editor";
9	import "../less/memo-editor.less";
10	
11	const getCursorPostion = (input: HTMLTextAreaElement) => {
12	  const { offsetLeft: inputX, offsetTop: inputY, selectionEnd: selectionPoint } = input;
13	  const div = document.createElement("div");
14	
15	  const copyStyle = window.getComputedStyle(input);
16	  for (const item of copyStyle) {
17	    div.style.setProperty(item, copyStyle.getPropertyValue(item));
18	  }
19	  div.style.position = "fixed";
20	  div.style.visibility = "hidden";
21	  div.style.whiteSpace = "pre-wrap";
22	
23	  const swap = ".";
24	  const inputValue = input.tagName === "INPUT" ? input.value.replace(/ /g, swap) : input.value;
25	  const textContent = inputValue.substring(0, selectionPoint || 0);
26	  div.textContent = textContent;
27	  if (input.tagName === "TEXTAREA") {
28	    div.style.height = "auto";
29	  }
30	
31	  const span = document.createElement("span");
32	  span.textContent = inputValue.substring(selectionPoint || 0) || ".";
33	  div.appendChild(span);
34	  document.body.appendChild(div);
35	  const { offsetLeft: spanX, offsetTop: spanY } = span;
36	  document.body.removeChild(div);
37	  return {
38	    x: inputX + spanX,
39	    y: inputY + spanY,
40	  };
41	};
42	
43	interface Props {}
44	
45	const MemoEditor: React.FC<Props> = () => {
46	  const editorState = useAppSelector((state) => state.editor);
47	  const tags = useAppSelector((state) => state.memo.tags);
48	  const [isTagSeletorShown, toggleTagSeletor] = useToggle(false);
49	  const [isUploadingResource, setIsUploadingResource] = useToggle(false);
50	  const editorRef = useRef<EditorRefActions>(null);
51	  const prevGlobalStateRef = useRef(editorState);
52	  const tagSeletorRef = useRef<HTMLDivElement>(null);
53	
54	  useEffect(() => {
55	    if (editorState.markMemoId && editorState.markMemoId !== UNKNOWN_ID) {
56	      const editorCurrentValue = editorRef.current?.getContent();
57	      const memoLinkText = `${editorCurrentValue ? "\n" : ""}Mark: [@MEMO](${editorState.markMemoId})`;
58	      editorRef.current?.insertText(memoLinkText);
59	      editorStateService.clearMarkMemo();
60	    }
61	
62	    if (
63	      editorState.editMemoId &&
64	      editorState.editMemoId !== UNKNOWN_ID &&
65	      editorState.editMemoId !== prevGlobalStateRef.current.editMemoId
66	    ) {
67	      const editMemo = memoService.getMemoById(editorState.editMemoId ?? UNKNOWN_ID);
68	      if (editMemo) {
69	        editorRef.current?.setContent(editMemo.content ?? "");
70	        editorRef.current?.focus();
71	      }
72	    }
73	
74	    prevGlobalStateRef.current = editorState;
75	  }, [editorState.markMemoId, editorState.editMemoId]);
76	
77	  useEffect(() => {
78	    const handlePasteEvent = async (event: ClipboardEvent) => {
79	      if (event.clipboardData && event.clipboardData.files.length > 0) {
80	        event.preventDefault();
81	        const file = event.clipboardData.files[0];
82	        const url = await handleUploadFile(file);
83	        if (url) {
84	          editorRef.current?.insertText(`![](${url})`);
85	        }
86	      }
87	    };
88	
89	    const handleDropEvent = async (event: DragEvent) => {
90	      if (event.dataTransfer && event.dataTransfer.files.length > 0) {
91	        event.preventDefault();
92	        const file = event.dataTransfer.files[0];
93	        const url = await handleUploadFile(file);
94	        if (url) {
95	          editorRef.current?.insertText(`![](${url})`);
96	        }
97	      }
98	    };
99	
100	    const handleClickEvent = () => {
101	      handleContentChange(editorRef.current?.element.value ?? "");
102	    };
103	
104	    const handleKeyDownEvent = () => {
105	      setTimeout(() => {
106	        handleContentChange(editorRef.current?.element.value ?? "");
107	      });
108	    };
109	
110	    editorRef.current?.element.addEventListener("paste", handlePasteEvent);
111	    editorRef.current?.element.addEventListener("drop", handleDropEvent);
112	    editorRef.current?.element.addEventListener("click", handleClickEvent);
113	    editorRef.current?.element.addEventListener("keydown", handleKeyDownEvent);
114	
115	    return () => {
116	      editorRef.current?.element.removeEventListener("paste", handlePasteEvent);
117	      editorRef.current?.element.removeEventListener("drop", handleDropEvent);
118	      editorRef.current?.element.removeEventListener("click", handleClickEvent);
119	      editorRef.current?.element.removeEventListener("keydown", handleKeyDownEvent);
120	    };
121	  }, []);
122	
123	  const handleUploadFile = useCallback(
124	    async (file: File) => {
125	      if (isUploadingResource) {
126	        return;
127	      }
128	
129	      setIsUploadingResource(true);
130	      const { type } = file;
131	
132	      if (!type.startsWith("image")) {
133	        return;
134	      }
135	
136	      try {
137	        const image = await resourceService.upload(file);
138	        const url = `/h/r/${image.id}/${image.filename}`;
139	
140	        return url;
141	      } catch (error: any) {
142	        toastHelper.error(error);
143	      } finally {
144	        setIsUploadingResource(false);
145	      }
146	    },
147	    [isUploadingResource]
148	  );
149	
150	  const handleSaveBtnClick = useCallback(async (content: string) => {
151	    if (content === "") {
152	      toastHelper.error("Content can't be empty");
153	      return;
154	    }
155	
156	    const { editMemoId } = editorStateService.getState();
157	
158	    try {
159	      if (editMemoId && editMemoId !== UNKNOWN_ID) {
160	        const prevMemo = memoService.getMemoById(editMemoId ?? UNKNOWN_ID);
161	
162	        if (prevMemo && prevMemo.content !== content) {
163	          await memoService.patchMemo({
164	            id: prevMemo.id,
165	            content,
166	          });
167	        }
168	        editorStateService.clearEditMemo();
169	      } else {
170	        await memoService.createMemo({
171	          content,
172	        });
173	        locationService.clearQuery();
174	      }
175	    } catch (error: any) {
176	      toastHelper.error(error.message);
177	    }
178	
179	    setEditorContentCache("");
180	  }, []);
181	
182	  const handleCancelBtnClick = useCallback(() => {
183	    editorStateService.clearEditMemo();
184	    editorRef.current?.setContent("");
185	    setEditorContentCache("");
186	  }, []);
187	
188	  const handleContentChange = useCallback((content: string) => {
189	    setEditorContentCache(content);
190	
191	    if (editorRef.current) {
192	      const selectionStart = editorRef.current.element.selectionStart;
193	      const prevString = content.slice(0, selectionStart);
194	      const nextString = content.slice(selectionStart);
195	
196	      if (prevString.endsWith("#") && (nextString.startsWith(" ") || nextString === "")) {
197	        toggleTagSeletor(true);
198	        updateTagSelectorPopupPosition();
199	      } else {
200	        toggleTagSeletor(false);
201	      }
202	
203	      editorRef.current?.focus();
204	    }
205	  }, []);
206	
207	  const handleTagTextBtnClick = useCallback(() => {
208	    if (!editorRef.current) {
209	      return;
210	    }
211	
212	    const currentValue = editorRef.current.getContent();
213	    const selectionStart = editorRef.current.element.selectionStart;
214	    const prevString = currentValue.slice(0, selectionStart);
215	    const nextString = currentValue.slice(selectionStart);
216	
217	    let nextValue = prevString + "# " + nextString;
218	    let cursorIndex = prevString.length + 1;
219	
220	    if (prevString.endsWith("#") && nextString.startsWith(" ")) {
221	      nextValue = prevString.slice(0, prevString.length - 1) + nextString.slice(1);
222	      cursorIndex = prevString.length - 1;
223	    }
224	
225	    editorRef.current.element.value = nextValue;
226	    editorRef.current.element.setSelectionRange(cursorIndex, cursorIndex);
227	    editorRef.current.focus();
228	    handleContentChange(editorRef.current.element.value);
229	  }, []);
230	
231	  const updateTagSelectorPopupPosition = useCallback(() => {
232	    if (!editorRef.current || !tagSeletorRef.current) {
233	      return;
234	    }
235	
236	    const seletorPopupWidth = 128;
