241	export type WitnessCancelledDuplicateFetchInstance =
242		WitnessCancelledDuplicateFetchCategoryEntry & {
243			cancelled: number;
244			corroboratingSuccesses: number;
245			/** The distinct response statuses of those successful fetches, ascending. */
246			corroboratingStatuses: number[];
247		};
248	
249	/**
250	 * Accounting for the cancelled-duplicate-fetch category. This is a category,
251	 * not an allowance: it removes nothing from the evidence, it re-files a named
252	 * and corroborated browser behavior into its own inventory where every instance
253	 * is recorded individually. Every other failed request continues through the
254	 * exact {@link WitnessFailedRequestInventory} and still fails the run, and a
255	 * cancelled fetch that matches `category` but finds no successful sibling is
256	 * left in that inventory too — which is to say it fails.
257	 *
258	 * `absent` records category members this run never observed, because the whole
259	 * point of the category is that the behavior is intermittent: a run that did
260	 * not race is recorded as not having raced rather than silently indistinguishable
261	 * from one that did. `uncorroborated` must stay empty by construction.
262	 */
263	export type WitnessCancelledDuplicateFetchInventory = {
264		policy: 'corroborated-browser-cancelled-duplicate-fetch';
265		corroborationRule: typeof WITNESS_CANCELLED_DUPLICATE_FETCH_RULE;
266		category: WitnessCancelledDuplicateFetchCategoryEntry[];
267		observed: WitnessCancelledDuplicateFetchInstance[];
268		absent: WitnessCancelledDuplicateFetchCategoryEntry[];
269		uncorroborated: [];
270		/** Cancelled fetches admitted by the category in this run, summed. */
271		admitted: number;
272		/**
273		 * Present exactly when the category declares a member outside the loopback
274		 * origin, and carrying the scope statement that governs those members. A run
275		 * whose category is entirely same-origin omits it, so an application that
276		 * never reached past loopback cannot be read as having claimed anything about
277		 * seams it does not have.
278		 */
279		nonLoopbackScope?: typeof WITNESS_CANCELLED_DUPLICATE_FETCH_NON_LOOPBACK_SCOPE;
280	};
281	
282	/**
283	 * One non-loopback seam the application reaches for and the harness answers
284	 * inside the browser context, pinned by method and query-free recorded path.
285	 *
286	 * This is an inventory, not an allowance: the point of naming every seam is
287	 * that a request to an endpoint nobody declared fails the run rather than being
288	 * absorbed into a total. Nothing here is a successful non-loopback request —
289	 * none of these left the machine — which is why `successfulNonLoopback` stays
290	 * zero alongside it.
291	 */
292	export type WitnessMockedNonLoopbackSeamEntry = { method: string; path: string };
293	
294	/**
295	 * One declared seam as this run actually observed it. `requests` is recorded
296	 * rather than pinned, because how many times a page reports to an analytics or
297	 * error endpoint is load timing; the statuses are the answers the harness gave.
298	 */
299	export type WitnessMockedNonLoopbackSeamObservation = WitnessMockedNonLoopbackSeamEntry & {
300		requests: number;
301		/** The distinct statuses the harness answered with, ascending. */
302		statuses: number[];
303	};
304	
305	/**
306	 * Exact, application-scoped accounting for the seams an application reaches for
307	 * outside loopback, held to the same non-masking discipline as the console and
308	 * failed-request inventories: every declared member is either observed or
309	 * explicitly absent, and anything observed outside the declared membership is
310	 * reported by its own path and fails the run.
311	 */
312	export type WitnessMockedNonLoopbackSeamInventory = {
313		policy: 'exact-app-scoped-mocked-non-loopback-seams';
314		pathPolicy: typeof WITNESS_NON_LOOPBACK_QUERY_FREE_PATH_RULE;
315		category: WitnessMockedNonLoopbackSeamEntry[];
316		observed: WitnessMockedNonLoopbackSeamObservation[];
317		absent: WitnessMockedNonLoopbackSeamEntry[];
318		outsideInventory: [];
319		/** None of these left the machine; the harness answered every one in-context. */
320		successfulNonLoopback: 0;
321	};
322	
323	/**
324	 * Resolved appearance measured from the live page for a closed list of probes.
325	 *
326	 * A claim that two lanes render the same has to be measured on laid-out
327	 * elements, not inferred from the stylesheet bytes that were shipped — an
328	 * application whose migration replaced a narrow style entry point with an
329	 * aggregate ships different bytes on purpose, and the only honest way to say
330	 * the difference is invisible is to read what the browser resolved.
331	 */
332	export type WitnessRenderedStyleMeasurement = {
333		label: string;
334		selector: string;
335		width: number;
336		height: number;
337		properties: Record<string, string>;
338	};
339	export type WitnessRenderedStyleEvidence = {
340		state: 'measured-resolved-styles';
341		probes: WitnessRenderedStyleMeasurement[];
342	};
343	
344	/**
345	 * Measured journey facts that only one application's own surfaces can express —
346	 * the settled state of a board after a drag, the counts a filter narrowed to,
347	 * the text a tooltip rendered.
348	 *
349	 * The generic runner carries this without inspecting it, which is deliberate:
350	 * inventing a shared vocabulary for facts that are not shared would either
351	 * flatten them into something unfalsifiable or push one application's nouns
352	 * into everyone else's schema. The strictness is not lost, it moves — the
353	 * application's own receipt schema narrows this to an exact shape and checks
354	 * every field of it, and because the whole record participates in that
355	 * application's behavior digest, a lane that measured something different
356	 * cannot agree with its own pair.
357	 */
358	export type WitnessApplicationJourneyEvidence = Record<string, unknown>;
359	
360	/**
361	 * One observed service-worker-script event, stripped of the two fields that
362	 * cannot reproduce: the wall-clock timestamp and the run-global sequence
363	 * number, which counts every other asset the lane happens to load. What
364	 * remains — who observed it, in what phase, for which path, with what detail —
365	 * is the substance of the observation and is identical run to run.
366	 */
367	export type WitnessServiceWorkerRequestEvent = {
368		source: string;
369		phase: string;
370		urlPath: string | null;
371		detail: Record<string, boolean | number | string | null>;
372	};
373	/** The same event with the number of times it was observed, for exact accounting. */
374	export type WitnessServiceWorkerRequestTally = WitnessServiceWorkerRequestEvent & {
375		count: number;
376	};
377	
378	export type WitnessRealAppRun = {
379		app: (typeof WITNESS_REAL_APP_NAMES)[number];
380		framework: 'react' | 'angularjs' | 'next' | 'angular';
381		lane: 'baseline' | 'migrated';
382		pass: 1 | 2;
383		result: 'pass';
384		interactions: Array<{ kind: WitnessGesture; selector: string }>;
385		assertions: string[];
386		routes: string[];
387		trackedEvents: string[];
388		witnessRecord: {
389			interactions: Array<{ kind: WitnessGesture; selector: string }>;
390			navigationPaths: string[];
391			trackedEventCounts: Record<string, number>;
392			consoleErrors: number;
393			pageErrors: number;
394			/**
395			 * Requests the browser failed, excluding the ones admitted by this run's
396			 * cancelled-duplicate-fetch category, which are recorded instance by
397			 * instance in {@link WitnessRealAppRun.cancelledDuplicateFetches}. A run
398			 * that declares no such category — every application here but the ones
399			 * that measured the behavior — has nothing to exclude, so this stays the
400			 * total number of browser-failed requests it has always been.
401			 */
402			failedRequests: number;
403		};
404		cleanPage: true;
405		offlineEvidence: WitnessOfflineEvidence;
406		servedStatic: {
407			transport: 'isolated-bounded-loopback-production-static';
408			documentFallback: 'index-only';
409			missingAssets: '404';
410			traversal: 'rejected';
411			inventory: { files: number; beforeSha256: string; afterSha256: string };
412			application: { path: 'index.html'; beforeSha256: string; afterSha256: string };
413			serviceWorkers: Array<{ path: string; beforeSha256: string; afterSha256: string }>;
414			byteIdentical: true;
415			hmrControls: false;
416			legacyMainPrecache:
417				| {
418						state: 'exact-completed';
419						responses: Array<{
420							method: 'GET';
421							pathname: string;
422							query: '?__uncache=versionless-deterministic';
423							destination: 'empty';
424							resolvedFile: string;
425							status: 200;
426							mime: string;
427							bytes: number;
428							sha256: string;
429							urlPath: string;
430							source: 'production-static-origin';
431						}>;
432				  }
433				| { state: 'not-applicable' };
434			phonecatOrdering:
435				| {
436						state: 'data-derived-full-order';
437						datasetSha256: string;
438						orderSha256: string;
439						rows: 20;
440						comparator: 'stable-lowercase-utf16-source-order-ties';
441				  }
442				| { state: 'not-applicable' };
443			phonecatImageTransition:
444				| {
445						state: 'data-derived-visible-transition';
446						detailSha256: string;
447						defaultImage: string;
448						nonDefaultImage: string;
449						hover: 'genuine-thumbnail-mouseover';
450						transition: 'genuine-ng-click';
451						heroVisibility: 'genuine-hover';
452				  }
453				| { state: 'not-applicable' };
454			nextPrerenderPayload?: WitnessNextPrerenderPayloadEvidence;
455		};
456		observerFinalization: {
457			state: 'target-closed';
458			detach: 'owned-detach-complete';
459			pageClose: 'owned-page-close-complete';
460			workerEvents: WitnessServiceWorkerTelemetry['workerEvents'];
461		};
462		semanticDigest: string;
463		successfulNonLoopback: 0;
464		consoleErrorInventory?: WitnessConsoleErrorInventory;
465		failedRequestInventory?: WitnessFailedRequestInventory;
466		cancelledDuplicateFetches?: WitnessCancelledDuplicateFetchInventory;
467		mockedNonLoopbackSeams?: WitnessMockedNonLoopbackSeamInventory;
468		renderedStyles?: WitnessRenderedStyleEvidence;
469		applicationJourney?: WitnessApplicationJourneyEvidence;
470		scrollSurface?: WitnessScrollSurface;
471		scrollAbsence?: WitnessMeasuredScrollAbsence;
472	};
473	
474	/**
475	 * Measured scroll evidence for one route that genuinely overflows the stated
476	 * viewport. The document extents are read from the live page, and the scroll
477	 * itself is a real wheel gesture the browser driver confirms moved the
478	 * viewport — the boolean is an observation, not a claim substituted for one.
479	 */
480	export type WitnessScrollSurface = {
481		state: 'measured-genuine-viewport-scroll';
482		route: string;
483		viewport: { width: number; height: number };
484		scrollHeight: number;
485		clientHeight: number;
486		wheelDeltaY: number;
487		scrolledFromTop: true;
488		scrolled: true;
489	};
490	
491	/**
492	 * The measured counterpart of {@link WitnessScrollSurface}: evidence that a
493	 * journey looked for a scroll surface and did not find one.
494	 *
495	 * An application that pins its document to the viewport and scrolls its own
496	 * inner panels instead has no scrollable document to gesture at, and inventing
497	 * one would be a false claim. So the same generic measurement that backs a
498	 * scroll claim is taken at every visited route and recorded here instead:
499	 * `scrollHeight` never exceeds `clientHeight`, which is why no scroll coverage
500	 * is claimed. Routes are recorded individually rather than summarized, so a
