641	export function parseWitnessReactLinkfreeReceipt(value: unknown): WitnessReactLinkfreeReceipt {
642		if (value === null || typeof value !== 'object' || Array.isArray(value))
643			throw new Error('React LinkFree Witness receipt must be an object');
644		const receipt = value as WitnessReactLinkfreeReceipt;
645		const expectedRuns = new Set(['baseline:1', 'baseline:2', 'migrated:1', 'migrated:2']);
646		const behaviors = new Set<string>();
647		const styles = new Set<string>();
648		if (
649			receipt.schemaVersion !== WITNESS_REACT_LINKFREE_SCHEMA ||
650			receipt.result !== 'pass' ||
651			receipt.fixture !== REACT_LINKFREE_FIXTURE ||
652			!exact(receipt.source, REACT_LINKFREE_SOURCE) ||
653			!exact(receipt.corpusRuling, WITNESS_REACT_LINKFREE_CORPUS_RULING) ||
654			receipt.canonicalReceipt?.path !== REACT_LINKFREE_RECEIPT_PATH ||
655			receipt.canonicalReceipt.canonicalDigest !== REACT_LINKFREE_CANONICAL_DIGEST ||
656			receipt.canonicalReceipt.sha256 !== REACT_LINKFREE_RECEIPT_SHA256 ||
657			receipt.stagedCorpus?.policy !==
658				'synthetic-profile-corpus-through-the-applications-own-codegen' ||
659			receipt.stagedCorpus.bundlerAuthoredBytesUnchanged !== true ||
660			receipt.stagedCorpus.bundlerAuthoredPaths < 1 ||
661			!exact(receipt.stagedCorpus.replacedPaths, ['data/', 'list.json']) ||
662			!Array.isArray(receipt.runs) ||
663			receipt.runs.length !== 4
664		)
665			throw new Error('React LinkFree Witness binding differs');
666		for (const run of receipt.runs) {
667			const key = `${run.lane}:${run.pass}`;
668			if (
669				!expectedRuns.delete(key) ||
670				run.app !== 'react-linkfree' ||
671				run.framework !== 'react' ||
672				run.result !== 'pass' ||
673				run.cleanPage !== true ||
674				run.successfulNonLoopback !== 0 ||
675				run.witnessRecord.pageErrors !== 0 ||
676				run.witnessRecord.failedRequests !== run.failedRequestInventory?.total ||
677				run.witnessRecord.consoleErrors !== run.consoleErrorInventory?.total ||
678				run.offlineEvidence.state !== 'not-applicable' ||
679				run.observerFinalization.workerEvents.length !== 0 ||
680				run.semanticDigest !== witnessReactLinkfreeRawDigest(run) ||
681				run.behaviorDigest !== witnessReactLinkfreeBehaviorDigest(run) ||
682				!exact(run.routes, WITNESS_REACT_LINKFREE_ROUTES)
683			)
684				throw new Error(`React LinkFree Witness run differs: ${key}`);
685			assertRedactedRoutes(run.routes, key);
686			assertConsoleErrorInventory(run.consoleErrorInventory, run.lane, key);
687			assertFailedRequestInventory(run.failedRequestInventory, run.lane, key);
688			assertMockedSeams(run.mockedNonLoopbackSeams, run.lane, key);
689			assertRenderedStyles(run.renderedStyles, key);
690			assertScrollSurface(run.scrollSurface, key);
691			assertApplicationJourney(run.applicationJourney, key);
692			behaviors.add(run.behaviorDigest);
693			styles.add(canonicalize(run.renderedStyles));
694		}
695		assertScrollSurface(receipt.scrollSurface, 'receipt');
696		if (
697			expectedRuns.size !== 0 ||
698			behaviors.size !== 1 ||
699			styles.size !== 1 ||
700			receipt.renderedStyleParity?.state !== 'measured-identical-resolved-styles' ||
701			receipt.renderedStyleParity.lanesAgree !== true ||
702			receipt.renderedStyleParity.probes !== WITNESS_REACT_LINKFREE_STYLE_PROBES.length ||
703			!exact(receipt.consoleErrors, WITNESS_REACT_LINKFREE_CONSOLE_ERRORS) ||
704			!exact(receipt.failedRequests, WITNESS_REACT_LINKFREE_FAILED_REQUESTS) ||
705			!exact(receipt.mockedSeams, WITNESS_REACT_LINKFREE_MOCKED_SEAMS) ||
706			receipt.router?.library !== 'react-router-dom-5' ||
707			receipt.router.dynamicSegment !== '/:username' ||
708			receipt.router.navigations !== WITNESS_REACT_LINKFREE_ROUTES.length ||
709			!exact(receipt.router.routes, WITNESS_REACT_LINKFREE_ROUTES) ||
710			receipt.mutation?.intendedFailure !== true ||
711			receipt.mutation.failure !== 'witness-semantic-assertion' ||
712			receipt.mutation.lane !== 'migrated' ||
713			receipt.mutation.restoredByteIdentically !== true ||
714			receipt.mutation.restoredRun !== 'pass' ||
715			receipt.mutation.beforeSha256 !== receipt.mutation.afterRestoreSha256 ||
716			receipt.mutation.beforeSha256 === receipt.mutation.mutatedSha256 ||
717			!behaviors.has(receipt.mutation.restoredBehaviorDigest) ||
718			!exact(receipt.readiness, {
719				reactLineage: { ready: 1, total: 4, counted: false },
720				overall: { ready: 3, total: 12 },
721			}) ||
722			receipt.locality?.mode !== 'offline' ||
723			receipt.locality.successfulNonLoopback !== 0 ||
724			receipt.locality.osWideIsolation !== false ||
725			!Array.isArray(receipt.nonclaims) ||
726			receipt.nonclaims.length === 0 ||
727			receipt.integrity?.algorithm !== 'sha256' ||
728			receipt.integrity.canonicalDigest !== witnessReactLinkfreeDigest(receipt)
729		)
730			throw new Error('React LinkFree Witness integrity differs');
731		return receipt;
732	}
733	
734	export function renderWitnessReactLinkfreeReceipt(receipt: WitnessReactLinkfreeReceipt): string {
735		const journey = receipt.runs[0]!.applicationJourney;
736		const inventoryLine = (lane: 'baseline' | 'migrated'): string =>
737			receipt.consoleErrors[lane]
738				.map((entry) => `${String(entry.count)}x \`${entry.message}\``)
739				.join('; ');
740		const seamLine = (lane: 'baseline' | 'migrated'): string =>
741			receipt.mockedSeams[lane].map((entry) => `\`${entry.method} ${entry.path}\``).join(', ');
742		return `# LinkFree v0.72.0 — direct Witness browser proof
743	
744	- Result: pass
745	- Canonical SHA-256: ${receipt.integrity.canonicalDigest}
746	- Runs: 2 baseline + 2 migrated production-static browser journeys
747	- Behavioral parity: ${receipt.runs[0]!.behaviorDigest}
748	- Dataset: SYNTHETIC. ${receipt.corpusRuling.why}
749	- How: ${receipt.corpusRuling.seam}; ${String(receipt.corpusRuling.applicationSourceEdits)} application source edits; the same corpus in both lanes; ${String(receipt.stagedCorpus.bundlerAuthoredPaths)} bundler-authored emitted paths proved byte identical to the committed build output
750	- Journey: the homepage, the searchable directory of ${String(journey.directory.profiles)} synthetic profiles, a typed search that narrows to ${String(journey.search.narrowed)} and a full clear that restores ${String(journey.search.afterClear)}, a real router navigation into a profile route, its ${String(journey.profile.links)} declared links, a hover that restyles a link, a measured wheel scroll and the application's own scroll-to-top control, and the not-found state behind the application's own example link
751	- Router: ${receipt.router.library} with a ${receipt.router.dynamicSegment} segment; the exact route sequence ${receipt.router.routes.map((route) => `\`${route}\``).join(' -> ')}
752	- Avatar cascade: the declared endpoint is answered ${String(journey.avatarCascade.declaredAnswer)} in context, the application's own onerror handler cascades to a second host, and that one is answered ${String(journey.avatarCascade.cascadedAnswer)}. Both are answered locally; neither leaves the machine.
753	- Mocked non-loopback seams (exact, per lane) — baseline: ${seamLine('baseline')}; migrated: ${seamLine('migrated')}
754	- Console-error inventory (exact, whole journey, per lane) — baseline: ${inventoryLine('baseline')}; migrated: ${inventoryLine('migrated')}
755	- Failed requests: none in either lane
756	- Rendered appearance: ${String(receipt.renderedStyleParity.probes)} probes measured off the live page in both lanes; ${receipt.renderedStyleParity.note}
757	- Scroll: ${receipt.scrollSurface.state} on ${receipt.scrollSurface.route} — scrollHeight ${String(receipt.scrollSurface.scrollHeight)} against clientHeight ${String(receipt.scrollSurface.clientHeight)} at ${String(receipt.scrollSurface.viewport.width)}x${String(receipt.scrollSurface.viewport.height)}
758	- Mutation proof: \`${receipt.mutation.seam}\` in \`${receipt.mutation.path}\` at offset ${String(receipt.mutation.offset)} made the journey red, byte-identical restoration made it green again
759	- React lineage readiness: unchanged at ${String(receipt.readiness.reactLineage.ready)}/${String(receipt.readiness.reactLineage.total)}; this vertical is not counted
760	
761	${receipt.nonclaims.map((claim) => `- ${claim}`).join('\n')}
762	`;
763	}
764	
765	export function witnessReactLinkfreeAggregateMember(digestValue: string) {
766		return {
767			id: 'witness-react-linkfree-v0-72-0',
768			framework: 'react',
769			track: 'production-readiness-direct-witness-create-react-app-5-to-vite8',
770			bundler: 'webpack-5.73.0-to-vite-8.0.16',
771			runtime: 'node-16.20.2-to-node-24.15.0',
772			result: 'pass',
773			receipt: WITNESS_REACT_LINKFREE_RECEIPT_PATH,
774			digest: digestValue,
775		};
776	}
777	
778	export async function verifyWitnessReactLinkfreeEvidence(rootDir = '.') {
779		const rootPath = resolve(rootDir);
780		const receiptPath = join(rootPath, WITNESS_REACT_LINKFREE_RECEIPT_PATH);
781		const receipt = parseWitnessReactLinkfreeReceipt(JSON.parse(await readFile(receiptPath, 'utf8')));
782		const canonicalBytes = await readFile(join(rootPath, receipt.canonicalReceipt.path));
783		if (sha256(canonicalBytes) !== receipt.canonicalReceipt.sha256)
784			throw new Error('React LinkFree canonical receipt bytes drifted');
785		const canonical = JSON.parse(canonicalBytes.toString('utf8')) as {
786			unit?: unknown;
787			fixture?: unknown;
788			integrity?: { canonicalDigest?: unknown };
789		};
790		if (
791			canonical.unit !== REACT_LINKFREE_UNIT ||
792			canonical.fixture !== REACT_LINKFREE_FIXTURE ||
793			canonical.integrity?.canonicalDigest !== receipt.canonicalReceipt.canonicalDigest
794		)
795			throw new Error('React LinkFree canonical receipt identity differs');
796		if (
797			(await readFile(join(dirname(receiptPath), 'receipt.md'), 'utf8')) !==
798			renderWitnessReactLinkfreeReceipt(receipt)
799		)
800			throw new Error('React LinkFree human Witness receipt differs');
801		return { valid: true as const, digest: receipt.integrity.canonicalDigest, artifacts: 0, receipt };
802	}
803

