type PageExpectApi = {
  /** Waits until the selector's trimmed text equals the expected string. */text(page: PageHandle, selector: string, expected: string, options?: ExpectWaitOptions): Promise<void>; /** Waits until the page body text contains / no longer contains fragments. */
  bodyText(page: PageHandle, expectation: BodyTextExpectation, options?: ExpectWaitOptions): Promise<void>;
  /**
   * Waits until the selector's element carries the attribute. With a string
   * `expected`, waits until the attribute equals that value; with `null`,
   * waits until the element exists without the attribute (absence).
   */
  attribute(page: PageHandle, selector: string, attributeName: string, expected?: string | null, options?: ExpectWaitOptions): Promise<void>; /** Waits until the selector matches an element in the DOM. */
  exists(page: PageHandle, selector: string, options?: ExpectWaitOptions): Promise<void>; /** Waits until the selector matches exactly the expected number of elements. */
  count(page: PageHandle, selector: string, expected: number, options?: ExpectWaitOptions): Promise<void>; /** Waits until the selector matches a visible element. */
  visible(page: PageHandle, selector: string, options?: ExpectWaitOptions): Promise<void>; /** Waits until every given computed style property matches. */
  computedStyle(page: PageHandle, selector: string, styles: Record<string, string>, options?: ExpectWaitOptions): Promise<void>;
  /**
   * Declaratively checks the recorded page evidence (navigations, console
   * errors, failed requests, tracked events) and reports every mismatch at
   * once. Event expectations wait (bounded) for their counts; the numeric
   * checks compare what the page record holds at that point.
   */
  outcome(page: PageHandle, expectation: PageOutcomeExpectation, options?: ExpectWaitOptions): Promise<void>;
  /**
   * Shortcut for the common healthy-page check: no post-load navigations,
   * no console/page errors, and no failed requests.
   */
  clean(page: PageHandle, options?: ExpectWaitOptions): Promise<void>;
};
/** What `expect.response.matches` checks against an environment response. */
type ResponseExpectation = {
  status?: number;
  ok?: boolean; /** Substring match against the lowercased content-type header. */
  contentType?: string; /** Substring match against the response body. */
  contains?: string;
};
type ExpectApi = {
  /**
   * The only edit/HMR assertion: declares the expected reaction to one edit
   * across every named environment (and the reserved `server` key), waits
   * for each to settle, then diffs expectation against the recorded outcome
   * and reports all mismatches at once.
   */
  edit(change: EditReceipt, expectation: EditExpectation, options?: ExpectWaitOptions): Promise<void>;
  page: PageExpectApi;
  html: {
    contains(html: string, fragment: string): Promise<void>;
  };
  response: {
    /** Asserts status / content-type / body facts of an environment fetch. */matches(response: EnvironmentResponse, expectation: ResponseExpectation): Promise<void>;
  };
  build: {
    environment(build: BuildHandle, name: string): Promise<void>;
    artifact(build: BuildHandle, path: string): Promise<void>;
    /**
     * Scans the build's emitted text artifacts and fails if any forbidden
     * string appears, listing every file and string that matched. The
     * canonical leakage check: `expect.build.forbids(build, ['node:fs'])`.
     */
    forbids(build: BuildHandle, forbidden: string[], options?: BuildForbidsOptions): Promise<void>;
  };
  artifact: {
    exists(build: BuildHandle, path: string): Promise<void>;
    text(build: BuildHandle, path: string, expectation: ArtifactTextExpectation): Promise<void>;
    json: {
      (artifact: ArtifactHandle, predicate: ArtifactJsonPredicate): Promise<void>;
      (build: BuildHandle, path: string, predicate: ArtifactJsonPredicate): Promise<void>;
    };
  };
};
type Measurement = {
  label: string;
  durationMs: number;
};
type ReceiptApi = {
  capture(label: string): Promise<void>;
  note(text: string): void;
  measure(label: string, fn: () => unknown | Promise<unknown>): Promise<Measurement>;
};
type ViteErrorEvidence = Record<string, unknown>;
type ViteModuleEvidence = {
  url: string;
  id: string | null;
  file: string | null;
};
type ViteUpdateEvidence = {
  type: string;
  path: string;
  acceptedPath: string;
} & Record<string, unknown>;
type VitePluginEvidence = {
  name: string;
  hook: string;
};
/**
 * A framework hot-channel message broadcast after an edit. Frameworks (for
 * example qwik with 'qwik:hmr') replace Vite's standard 'update' protocol
 * with their own messages; these are first-class HMR evidence.
 */
type ViteHotMessageEvidence = {
  name: string;
  data?: unknown;
};
/**
 * Normalized per-environment reaction to one project edit. The `hmr` field is
 * the headline classification and uses the exact words the `expect.edit`
 * vocabulary uses; the raw updates, messages, and reload payloads stay
 * recorded underneath it.
 */
type EnvironmentEditOutcome = {
  name: string;
  kind: 'browser' | 'server' | 'worker' | 'custom';
  /**
   * 'accepted' = an HMR update was applied with no full reload.
   * 'full-reload' = the environment reloaded (browser document or server
   * module runner). 'none' = no update and no reload were observed.
   */
  hmr: 'accepted' | 'full-reload' | 'none';
  restart: boolean;
  error: ViteErrorEvidence | null;
  invalidated: ViteModuleEvidence[];
  updates: ViteUpdateEvidence[]; /** Framework hot-channel messages broadcast after the edit. */
  messages: ViteHotMessageEvidence[];
  plugins: VitePluginEvidence[];

