		beforeFilter: number;
		narrowed: number;
		afterClear: number;
		wideningGesture: 'select-all-then-backspace';
		projectionRecordsDuringFilter: 0;
		originRequestsDuringFilter: 0;
	};
	tagFilter: {
		state: 'measured-client-side-tag-filter';
		tags: string[];
		tag: string;
		narrowed: number;
		afterRestore: number;
		projectionRecordsDuringFilter: 0;
		originRequestsDuringFilter: 0;
