 * count is bounded from below by those hovers rather than pinned to an unstable
 * number. The bound is checked, not erased.
 */
export const WITNESS_REACT_MEMOS_TRACKED_EVENTS = Object.freeze({
	click: 12,
	input: 63,
	keydown: 65,
	mouseoverAtLeast: 3,
